func isValidBST(root *TreeNode) bool {
	if root == nil {
		return true
	}
	order := make([]int, 0)
	inorder(root, &order)
	for i := 1; i < len(order); i++ {
		if order[i] <= order[i-1] {
			return false
		}
	}
	return true
}

func inorder(root *TreeNode, order *[]int) {
	if root == nil {
		return
	}
	inorder(root.Left, order)
	*order = append(*order, root.Val)
	inorder(root.Right, order)
}

